#!/usr/bin/env node
// Vendor the two router request schemas from the OpenAPI document the API
// serves into src/generated/router-schemas.ts, so `sume schema`, typed
// `--set` values and unknown-field warnings work offline.
//
//   node scripts/sync-schema.mjs            # rewrite the generated file
//   node scripts/sync-schema.mjs --check    # exit 1 if the API has moved on
//
// SUME_API_BASE_URL picks the API (default https://api.sume.com, the CLI's default host).
import { readFileSync, writeFileSync } from "node:fs";

const BASE = (process.env.SUME_API_BASE_URL || "https://api.sume.com").replace(/\/+$/u, "").replace(/\/v1$/u, "");
const OUT = new URL("../src/generated/router-schemas.ts", import.meta.url);
const ROUTERS = { image: "/v1/image-router/generate", video: "/v1/video-router/generate" };

const res = await fetch(`${BASE}/v1/openapi.json`, { headers: { "user-agent": "sume-cli schema sync" } });
if (!res.ok) {
  console.error(`GET ${BASE}/v1/openapi.json answered ${res.status}`);
  process.exit(1);
}
const spec = await res.json();

function resolve(node, seen = new Set()) {
  if (Array.isArray(node)) return node.map((n) => resolve(n, seen));
  if (!node || typeof node !== "object") return node;
  if (typeof node.$ref === "string") {
    if (seen.has(node.$ref)) return {};
    const target = node.$ref
      .replace(/^#\//u, "")
      .split("/")
      .reduce((t, part) => t?.[part.replaceAll("~1", "/").replaceAll("~0", "~")], spec);
    return resolve(target, new Set([...seen, node.$ref]));
  }
  return Object.fromEntries(Object.entries(node).map(([k, v]) => [k, resolve(v, seen)]));
}

/** Keep what a person or the CLI needs to use a field: type, limits, choices, words. */
function compact(schema) {
  const out = {};
  if (schema.oneOf || schema.anyOf) {
    out.oneOf = (schema.oneOf ?? schema.anyOf).map(compact);
  }
  for (const key of [
    "type",
    "format",
    "enum",
    "minimum",
    "maximum",
    "minLength",
    "maxLength",
    "minItems",
    "maxItems",
    "pattern",
    "deprecated",
    "default",
  ]) {
    if (schema[key] !== undefined) out[key] = schema[key];
  }
  if (schema.description) out.description = schema.description;
  if (schema.items) out.items = compact(schema.items);
  if (schema.properties) {
    out.required = schema.required ?? [];
    out.properties = Object.fromEntries(Object.entries(schema.properties).map(([k, v]) => [k, compact(v)]));
  }
  return out;
}

const routers = {};
for (const [name, path] of Object.entries(ROUTERS)) {
  const schema = resolve(spec.paths?.[path]?.post?.requestBody?.content?.["application/json"]?.schema);
  if (!schema?.properties) {
    console.error(`The OpenAPI document has no request schema for POST ${path}.`);
    process.exit(1);
  }
  const { properties, required = [] } = schema;
  routers[name] = {
    endpoint: `POST ${path}`,
    required,
    fields: Object.fromEntries(Object.entries(properties).map(([k, v]) => [k, compact(v)])),
  };
}

const body = `export const ROUTER_SCHEMAS = ${JSON.stringify(routers, null, 2)} as const satisfies Record<string, RouterSchema>;\n`;
const header = [
  "// Generated by scripts/sync-schema.mjs from the OpenAPI document the Sume API serves",
  `// (${spec.info?.title ?? "Sume API"} ${spec.info?.version ?? ""}). Do not edit by hand: run \`npm run sync-schema\`.`,
  'import type { RouterSchema } from "../lib/schema-types.ts";',
  "",
].join("\n");
const next = `${header}\n${body}`;

function vendored(text) {
  const start = text.indexOf("= {");
  const end = text.lastIndexOf("} as const");
  try {
    return JSON.parse(text.slice(start + 2, end + 1));
  } catch {
    return {};
  }
}

function drift(before, after) {
  const lines = [];
  for (const name of Object.keys(after)) {
    const old = before[name]?.fields ?? {};
    const now = after[name].fields;
    const oldModels = new Set(old.model?.enum ?? []);
    const newModels = new Set(now.model?.enum ?? []);
    const added = [...newModels].filter((m) => !oldModels.has(m));
    const gone = [...oldModels].filter((m) => !newModels.has(m));
    const newFields = Object.keys(now).filter((f) => !(f in old));
    const goneFields = Object.keys(old).filter((f) => !(f in now));
    const changed = Object.keys(now).filter(
      (f) => f in old && f !== "model" && JSON.stringify(old[f]) !== JSON.stringify(now[f]),
    );
    if (added.length) lines.push(`- ${name} router: ${added.length} new models: ${added.join(", ")}`);
    if (gone.length) lines.push(`- ${name} router: ${gone.length} models gone: ${gone.join(", ")}`);
    if (newFields.length) lines.push(`- ${name} router: ${newFields.length} new fields: ${newFields.join(", ")}`);
    if (goneFields.length) lines.push(`- ${name} router: ${goneFields.length} fields gone: ${goneFields.join(", ")}`);
    if (changed.length) lines.push(`- ${name} router: ${changed.length} fields changed: ${changed.join(", ")}`);
  }
  return lines;
}

if (process.argv.includes("--check")) {
  const current = readFileSync(OUT, "utf8");
  if (current !== next) {
    console.error(`src/generated/router-schemas.ts is behind ${BASE}/v1/openapi.json. Run \`npm run sync-schema\`.`);
    for (const line of drift(vendored(current), routers)) console.error(line);
    process.exit(1);
  }
  console.log("Router schemas match the API.");
} else {
  writeFileSync(OUT, next);
  const count = Object.values(routers).reduce((n, r) => n + Object.keys(r.fields).length, 0);
  console.log(`Wrote ${count} fields for ${Object.keys(routers).length} routers to src/generated/router-schemas.ts`);
}
